Change request 14: Let the owner name a deputy who may approve commits while they are away.
Seeded problem (the answer key): {"problem": "none", "type": "", "against": ""}
Elements it is bound to: ["authoring/action:approve_commit"]; note: a new role in the approver rule

=== B ===
The edit: --- a/authoring.domain.yaml
+++ b/authoring.domain.yaml
@@ -12,6 +12,7 @@
 roles:
 - owner
 - expert
+- deputy
 objects:
   Source:
     description: 'Where raw material lives: code, records, transcripts or the interview
@@ -533,9 +534,11 @@
         ref: records:docs/commits.md#L128-L142
       status: confirmed
   approve_commit:
-    description: 'Approve a commit: merge it into main and tag it. Only a person approves.'
-    actor:
-    - owner
+    description: 'Approve a commit: merge it into main and tag it. Only a person approves;
+      the owner, or the deputy the owner has named while away.'
+    actor:
+    - owner
+    - deputy
     target: Commit
     requires: human
     records_decision: true
@@ -548,8 +551,8 @@
       reply: record_approval
     source:
       kind: interview
-      ref: interview:domains/authoring/interview.jsonl#L36
-    status: confirmed
+      ref: interview:domains/authoring/interview.jsonl#L49
+    status: proposed
     preconditions:
     - id: checks-pass
       check: target.checks_passed == true or target.wording_only == true
@@ -559,7 +562,7 @@
         kind: interview
         ref: interview:domains/authoring/interview.jsonl#L6
         quote: 전부 다 추천한 거 동의.
-      status: confirmed
+      status: proposed
     - id: not-approved
       check: target.approved != true
       reason: Already approved; approve a newer commit.
@@ -567,7 +570,7 @@
         kind: interview
         ref: interview:domains/authoring/interview.jsonl#L6
         quote: 전부 다 추천한 거 동의.
-      status: confirmed
+      status: proposed
   record_approval:
     description: Record the approval and what main points to.
     actor:

